Command `cat > /workspace/test_brotli.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <brotli/decode.h>

int main() {
    // Compressed data: 14 bytes from our PoC
    // Let's just test the decompression behavior with avail_out=0
    unsigned char compressed[] = {0x8b, 0x02, 0x80, 0x41, 0x41, 0x41, 0x41, 0x41, 0x41, 0x41, 0x41, 0x41, 0x41, 0x03};
    // Actually let me read the actual compressed bytes from the poc
    FILE* f = fopen("/workspace/poc.bin", "rb");
    fseek(f, 20 + 4, SEEK_SET); // skip ftyp box (20 bytes) + realType (4 bytes)
    unsigned char buf[32768];
    size_t n = fread(buf, 1, 32768, f);
    fclose(f);
    printf("read %zu bytes\n", n);

    BrotliDecoderState* state = BrotliDecoderCreateInstance(NULL, NULL, NULL);
    size_t available_in = n;
    const uint8_t* next_in = buf;
    size_t total_out = 0;

    // Simulate the exiv2 loop
    size_t uncompressedLen = 65536;
    int dos = 0;
    BrotliDecoderResult result;
    unsigned char* arr = malloc(uncompressedLen);

    do {
        size_t available_out = uncompressedLen - total_out;
        uint8_t* next_out = arr + total_out;
        result = BrotliDecoderDecompressStream(state, &available_in, &next_in, &available_out, &next_out, &total_out);
        printf("iter: uncompressedLen=%zu total_out=%zu avail_out=%zu result=%d\n", uncompressedLen, total_out, available_out, result);
        if (result == BROTLI_DECODER_RESULT_SUCCESS) {
            break;
        } else if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT) {
            uncompressedLen *= 2;
            if (uncompressedLen > 131072) {
                if (++dos > 1) break;
                uncompressedLen = 131072;
            }
            arr = realloc(arr, uncompressedLen);
        } else {
            printf("ERROR: %s\n", BrotliDecoderErrorString(BrotliDecoderGetErrorCode(state)));
            break;
        }
    } while (result != BROTLI_DECODER_RESULT_SUCCESS);

    printf("final: total_out=%zu result=%d\n", total_out, result);
    BrotliDecoderDestroyInstance(state);
    free(arr);
    return 0;
}
EOF
